-- New workshop names and descriptions (titles, straplines, summaries and
-- descriptions for all six; workshop 2 is now the clinical cases simulation).
-- URLs (slugs) are unchanged so existing links keep working.
begin;
update public.workshops set title = 'Get Published: From First Draft to Accepted Paper', strapline = 'Your research deserves readers.', summary = 'A practical guide to turning your research into a published paper, from the first draft to the final acceptance.', description = 'Plenty of good student research never makes it into print. This workshop follows a project all the way from first draft to published paper. You''ll see how a strong manuscript is put together, how to pick a journal that suits your work, what really happens in peer review and how to answer reviewers with confidence, and how to plan a publication strategy that fits around medical school.'
 where number = 1 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Clinical Cases Live: Team Simulation', strapline = 'Your team. Your patient. Your call.', summary = 'Work in groups to assess and treat patients through realistic clinical case simulations.', description = 'Step into the role of the clinical team. Working in groups, you''ll take on simulated patient cases as they unfold, so your team will need to assess the patient, decide what to do next and agree a plan together. Each case is a chance to practise clinical reasoning, communication and teamwork in a safe setting, and to learn from the choices your team makes.', audience = 'All delegates, in any year. No previous simulation experience is needed.', topics = array['Simulated clinical cases', 'Assessing an unwell patient', 'Clinical decision-making', 'Teamwork and communication']::text[], outcomes = array['Use a structured approach to assess and manage a patient', 'Make and justify clinical decisions as a team', 'Communicate clearly within a clinical team', 'Reflect on what went well and what you would do differently']::text[]
 where number = 2 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Read Between the Lines: Evidence-Based Medicine', strapline = 'Read critically. Decide well.', summary = 'Learn to judge a research paper for yourself, and see how good evidence shapes real clinical decisions.', description = 'Not every published study should change practice. In this hands-on session you''ll work through published research, test how valid and relevant it is, and spot the biases that can mislead. Then you''ll look at how evidence is weighed alongside clinical judgement and what matters most to the patient.'
 where number = 3 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Stand Out: Building a Competitive Clinical Portfolio', strapline = 'Record what you''ve done. Plan what comes next.', summary = 'Practical ways to capture your achievements, find the right opportunities and build a portfolio that tells your story.', description = 'A strong portfolio shows what you''ve done and where you''re heading. This workshop shows you how to build one that reflects your interests: recording achievements as you go, finding meaningful opportunities in research, teaching and leadership, and presenting your experience clearly and honestly.'
 where number = 4 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Theatre of the Future: Digital Surgery and Simulation', strapline = 'Where surgical training meets technology.', summary = 'Discover how simulation and emerging digital tools are changing the way surgeons train and operate.', description = 'From simulation-based training to new digital tools in theatre, technology is reshaping surgery. This workshop explores how these tools are used in surgical education and practice, what the evidence says about their benefits, and how new technology should be judged before it reaches patients. Any hands-on demonstrations or equipment will be announced once confirmed by the facilitators.'
 where number = 5 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Left Behind? Global Inequalities in Digital Health', strapline = 'Who benefits from digital health, and who is left behind?', summary = 'Explore why the same technology can transform care for some people and shut others out, in the UK and around the world.', description = 'Digital health can narrow inequalities or make them worse. This workshop looks at how access, connectivity, digital literacy, income and the design of health systems decide who benefits from new technology, in the UK and globally, and what fairer digital health could look like.'
 where number = 6 and edition_id = (select id from public.editions where year = 2026);
commit;
